import{_ as u,a0 as o,w as p,s as d,ao as n,I as l,x as s,a1 as e,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"構建基礎包的基礎知識 | LCTT x X-CMD","titleTemplate":false,"description":"構建基礎包的基礎知識 | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"構建基礎包的基礎知識 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"構建基礎包的基礎知識 | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20211019 What is Build Essential Package in Ubuntu- How to Install it","title":"構建基礎包的基礎知識","tag":"202111","desc":""},"relativePath":"202111/20211019 What is Build Essential Package in Ubuntu- How to Install it.md","filePath":"[post].md"}'),r={name:"202111/20211019 What is Build Essential Package in Ubuntu- How to Install it.md"};function b(g,t,h,k,m,f){const i=o("Link");return p(),d("div",null,[t[27]||(t[27]=n('<h1 id="構建基礎包的基礎知識" tabindex="-1">構建基礎包的基礎知識 <a class="header-anchor" href="#構建基礎包的基礎知識" aria-label="Permalink to “構建基礎包的基礎知識”">​</a></h1><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/10/Build-Essential-Ubuntu.png?resize=800%2C450&amp;ssl=1" alt=""></p><blockquote><p>這是一篇快速提示，旨在給 Ubuntu 的新用户解釋構建基礎包是什麼、它的用處和安裝步驟。</p></blockquote><p>在 Ubuntu 中安裝構建基礎包（<code>build-essential</code>），只需要在終端中簡單輸入這個命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update &amp;&amp; sudo apt install build-essential</span></span></code></pre></div><p>但圍繞它有幾個問題，你可能想知道答案：</p><ul><li>什麼是構建基礎包？</li><li>它包含什麼內容？</li><li>為什麼要安裝它（如果安裝的話）？</li><li>如何安裝它？</li><li>如何刪除它？</li></ul><h3 id="什麼是-ubuntu-中的構建基礎包" tabindex="-1">什麼是 Ubuntu 中的構建基礎包？ <a class="header-anchor" href="#什麼是-ubuntu-中的構建基礎包" aria-label="Permalink to “什麼是 Ubuntu 中的構建基礎包？”">​</a></h3><p>構建基礎包（<code>build-essential</code>）實際上是屬於 Debian 的。在它裏面其實並不是一個軟件。它包含了創建一個 Debian 包（<code>.deb</code>）所需的軟件包列表。這些軟件包包括 <code>libc</code>、<code>gcc</code>、<code>g++</code>、<code>make</code>、<code>dpkg-dev</code> 等。構建基礎包包含這些所需的軟件包作為依賴，所以當你安裝它時，你只需一個命令就能安裝所有這些軟件包。</p><p>請不要認為構建基礎包是一個可以在一個命令中神奇地安裝從 Ruby 到 Go 的所有開發工具的超級軟件包。它包含一些開發工具，但不是全部。</p><h4 id="你為什麼要安裝構建基礎包" tabindex="-1">你為什麼要安裝構建基礎包？ <a class="header-anchor" href="#你為什麼要安裝構建基礎包" aria-label="Permalink to “你為什麼要安裝構建基礎包？”">​</a></h4><p>它用來從應用的源代碼創建 DEB 包。一個普通用户不會每天都去創建 DEB 包，對嗎？</p>',12)),l("p",null,[t[3]||(t[3]=s("然而，有些用户可能會使用他們的 Ubuntu Linux 系統進行軟件開發。如果你想 ",-1)),e(i,{href:"https://itsfoss.com/run-c-program-linux/"},{default:a(()=>[...t[0]||(t[0]=[s("在 Ubuntu 中運行 c 程序",-1)])]),_:1}),t[4]||(t[4]=s("，你需要 gcc 編譯器。如果你想 ",-1)),e(i,{href:"https://itsfoss.com/c-plus-plus-ubuntu/"},{default:a(()=>[...t[1]||(t[1]=[s("在 Ubuntu 中運行 C++ 程序",-1)])]),_:1}),t[5]||(t[5]=s("，你需要 g++ 編譯器。如果你要使用一個不尋常的、只能從源代碼中獲得的軟件，你的系統會拋出 “",-1)),e(i,{href:"https://itsfoss.com/make-command-not-found-ubuntu/"},{default:a(()=>[...t[2]||(t[2]=[s("make 命令未找到的錯誤",-1)])]),_:1}),t[6]||(t[6]=s("”，因為你需要先安裝 ",-1)),t[7]||(t[7]=l("code",null,"make",-1)),t[8]||(t[8]=s(" 工具。",-1))]),t[28]||(t[28]=l("p",null,"當然，所有這些都可以單獨安裝。然而，利用構建基礎包的優勢，一次性安裝所有這些開發工具要容易得多。這就是你得到的好處。",-1)),l("p",null,[t[10]||(t[10]=s("這就像 ",-1)),e(i,{href:"https://itsfoss.com/install-media-codecs-ubuntu/"},{default:a(()=>[...t[9]||(t[9]=[s("ubuntu-restricted-extras 包允許你一次安裝幾個媒體編解碼器",-1)])]),_:1}),t[11]||(t[11]=s("。",-1))]),t[29]||(t[29]=n('<p>現在你知道了這個包的好處，讓我們看看如何安裝它。</p><h3 id="在-ubuntu-linux-中安裝構建基礎包" tabindex="-1">在 Ubuntu Linux 中安裝構建基礎包 <a class="header-anchor" href="#在-ubuntu-linux-中安裝構建基礎包" aria-label="Permalink to “在 Ubuntu Linux 中安裝構建基礎包”">​</a></h3><p>在 Ubuntu 中按 <code>Ctrl+Alt+T</code> 快捷鍵打開終端，輸入以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span></code></pre></div><p>使用 <code>sudo</code> 命令，你會被要求輸入你的賬户密碼。當你輸入時，屏幕上沒有任何顯示。這沒問題。這在大多數 Linux 系統中都是這樣的。盲打輸入你的密碼，然後按回車鍵。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/10/apt-update.png?resize=800%2C467&amp;ssl=1" alt=""></p><p><code>apt update</code> 命令刷新了本地軟件包的緩存。這對於一個新安裝的 Ubuntu 來説是必不可少的。</p><p>之後，運行下面的命令來安裝構建基礎包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install build-essential</span></span></code></pre></div><p>它應該顯示所有要安裝的軟件包。當要求確認時按 <code>Y</code>：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/10/install-build-essential-ubuntu.png?resize=800%2C434&amp;ssl=1" alt=""></p><p>等待安裝完成。就好了。</p><h3 id="從-ubuntu-中刪除構建基礎包" tabindex="-1">從 Ubuntu 中刪除構建基礎包 <a class="header-anchor" href="#從-ubuntu-中刪除構建基礎包" aria-label="Permalink to “從 Ubuntu 中刪除構建基礎包”">​</a></h3><p>保留這些開發工具不會損害你的系統。但如果你的磁盤空間不足，你可以考慮刪除它。</p><p>在 Ubuntu 中，由於有 <code>apt remove</code> 命令，刪除軟件很容易：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt remove build-essential</span></span></code></pre></div><p>運行 <code>autoremove</code> 命令來刪除剩餘的依賴包也是一個好主意：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt autoremove</span></span></code></pre></div><p>你現在知道了構建基礎包的基礎知識（雙關語）。希望對你有用~</p><hr>',20)),l("p",null,[t[13]||(t[13]=s("via: ",-1)),e(i,{href:"https://itsfoss.com/build-essential-ubuntu/"},{default:a(()=>[...t[12]||(t[12]=[s("https://itsfoss.com/build-essential-ubuntu/",-1)])]),_:1})]),l("p",null,[t[18]||(t[18]=s("作者：",-1)),e(i,{href:"https://itsfoss.com/author/abhishek/"},{default:a(()=>[...t[14]||(t[14]=[s("Abhishek Prakash",-1)])]),_:1}),t[19]||(t[19]=s(" 選題：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:a(()=>[...t[15]||(t[15]=[s("lujun9972",-1)])]),_:1}),t[20]||(t[20]=s(" 譯者：",-1)),e(i,{href:"https://github.com/geekpi"},{default:a(()=>[...t[16]||(t[16]=[s("geekpi",-1)])]),_:1}),t[21]||(t[21]=s(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:a(()=>[...t[17]||(t[17]=[s("wxy",-1)])]),_:1})]),l("p",null,[t[24]||(t[24]=s("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[22]||(t[22]=[s("LCTT",-1)])]),_:1}),t[25]||(t[25]=s(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:a(()=>[...t[23]||(t[23]=[s("Linux中國",-1)])]),_:1}),t[26]||(t[26]=s(" 榮譽推出",-1))])])}const c=u(r,[["render",b]]);export{T as __pageData,c as default};
